/* Majlis — assessment question banks (data only). Loaded before app.js. */

/* Philosophy and politics/society are statements: you say how much you agree with each, on one scale. */
const LIKERT = ["Strongly agree", "Agree", "Neutral or unsure", "Disagree", "Strongly disagree"];

/* ======================================================================
   Philosophy test: one claim per statement, in plain words. lean = what agreeing pushes on the six axes
   (see PHIL_AXES): strongly agree counts it in full, agree half, neutral nothing, and disagreeing the
   same amounts the other way. Statements are worded from both ends, so agreeing with everything doesn't
   tilt the result.
   ====================================================================== */
const PHIL_QUESTIONS = [
  { q: "It would be right to divert a runaway train onto a track where it will kill one person, if that saves five others.", lean: {E: 2} },
  { q: "Some moral rules must never be broken, whatever the consequences.", lean: {E: -2} },
  { q: "If you could do wrong and never be caught, there would be no good reason left to act fairly.", lean: {E: 2, V: 1} },
  { q: "It is wrong to believe anything without enough evidence for it.", lean: {K: 2} },
  { q: "If a machine destroyed your body and built an exact copy with all your memories, the copy would really be you.", lean: {M: 2} },
  { q: "We can never be certain that the world outside our own minds exists.", lean: {C: 2} },
  { q: "Some actions are morally wrong whatever any person or culture believes about them.", tag: 'morality', lean: {V: -2} },
  { q: "Our choices are not fully decided by earlier causes; we could genuinely have chosen differently.", tag: 'freewill', lean: {W: -2} },
  { q: "If something seems clearly true when we think it over carefully, that is good evidence it is true, even without proof.", lean: {K: -2} },
  { q: "An action can be wrong in one culture and right in another, without either culture being mistaken.", lean: {V: 2} },
  { q: "The mind can go on existing after the body dies.", lean: {M: -2} },
  { q: "Believing in God can be reasonable even without any argument or evidence for it.", lean: {K: -2} },
  { q: "Some things are more beautiful than others, regardless of anyone's personal taste.", lean: {V: -2} },
  { q: "Over the centuries, humanity has made real moral progress.", lean: {C: -2} },
  { q: "Criminals should be punished because they deserve it, even if the punishment prevents no future crime.", lean: {E: -2, W: -1} },
  { q: "The mind is nothing more than the physical activity of the brain.", tag: 'pp', lean: {M: 2} },
  { q: "There is a God who created the universe.", tag: 'pp', lean: {M: -2, K: -1} },
  { q: "Everything we know about the world ultimately comes from experience and observation.", tag: 'pp', lean: {K: 2} },
  { q: "Whether an action is right or wrong depends only on its consequences.", tag: 'pp', lean: {E: 2} },
  { q: "Each of us has a soul or inner self that stays the same throughout our life.", tag: 'pp', lean: {M: -2} },
  { q: "Our best scientific theories describe the world as it really is, including the parts we cannot observe.", tag: 'pp', lean: {K: 2, C: -1} },
  { q: "Lying is wrong even when a lie would save someone's life.", tag: 'sc', lean: {E: -2} },
  { q: "It would be right for a surgeon to secretly sacrifice one patient to save five others with his organs.", tag: 'sc', lean: {E: 2} },
  { q: "A promise should be kept even when breaking it would do more good.", tag: 'sc', lean: {E: -2} },
  { q: "A life of perfect happiness inside a simulation would be just as good as a real life.", tag: 'sc', lean: {E: 2} },
  { q: "A computer could one day have real thoughts and feelings, not just imitate them.", tag: 'sc', lean: {M: 2} },
  { q: "Conscious experience, such as what it is like to see red, cannot be fully explained by facts about the brain.", tag: 'sc', lean: {M: -2} },
  { q: "Some questions about identity, such as whether a fully rebuilt ship is still the same ship, have no true answer.", tag: 'sc', lean: {C: 2} },
  { q: "It is quite possible that we are living in a computer simulation.", tag: 'sc', lean: {C: 2} },
  { q: "Free will is an illusion: the brain decides before we are aware of choosing.", tag: 'sc', lean: {W: 2} },
  { q: "A drunk driver who kills someone deserves more blame than an equally drunk driver who happened to get home safely.", tag: 'sc', lean: {E: 2} },
  { q: "Free speech should protect even people who want to abolish free speech.", tag: 'sc', lean: {E: -2} },
  { q: "Making animals suffer is wrong even when it brings big benefits to humans.", tag: 'sc', lean: {E: -1, V: -1} },
  { q: "Slavery was wrong even in times when almost everyone accepted it.", tag: 'sc', lean: {V: -2} },
  { q: "Mathematical truths, such as 2 + 2 = 4, would be true even if no one had ever existed.", tag: 'sc', lean: {V: -2} },
  { q: "When two explanations fit the facts equally well, the simpler one is more likely to be true.", tag: 'sc', lean: {K: 2} },
  { q: "Reports of miracles should almost never be believed.", tag: 'sc', lean: {K: 2, C: 1} },
  { q: "Nothing exists beyond the natural world that science studies.", tag: 'sc', lean: {M: 2, K: 1} },
  { q: "The universe exists because something beyond it, such as God, brought it into being.", tag: 'sc', lean: {M: -2} },
  { q: "Life has a meaning that exists whether or not we choose to give it one.", tag: 'sc', lean: {V: -2, M: -1} },
  { q: "Death is simply the end of a person; nothing of us carries on.", tag: 'sc', lean: {M: 2} },
  { q: "A just society should put the worst-off first, even if that means less wealth or happiness overall.", tag: 'sc', lean: {E: -2} },
  { q: "Long-standing traditions deserve respect even when we can't see what they are for.", tag: 'sc', lean: {K: -2} },
  { q: "Whatever our circumstances, each of us is fully responsible for what we make of our life.", tag: 'sc', lean: {W: -2} },
  { q: "If an argument seems flawless but leads to a conclusion that seems absurd, we should accept the conclusion.", tag: 'sc', lean: {K: 2} },
].map(p => Object.assign(p, { opts: LIKERT }));

